        WHERE d.[ServiceRequestId] = [t1].[Id]
    ) THEN 1 ELSE 0 END AS bit) AS [tHas_Report],
    CAST(CASE WHEN EXISTS (
        SELECT 1
        FROM [Sale].[ServiceRequestDetail] d
        INNER JOIN [Sale].[ServiceRequestPart] p ON p.[ServiceRequestDetailId] = d.[Id]
        WHERE d.[ServiceRequestId] = [t1].[Id]
    ) THEN 1 ELSE 0 END AS bit) AS [tHas_RequestPart],
    CAST(CASE WHEN EXISTS (
        SELECT 1
        FROM [Sale].[ServiceRequestDetail] d
        INNER JOIN [Sale].[WorkReport] wr ON wr.[ServiceRequestDetailId] = d.[Id]
        INNER JOIN [Sale].[WorkReportAttachment] wa ON wa.[WorkReportId] = wr.[Id]
        WHERE d.[ServiceRequestId] = [t1].[Id]
    ) THEN 1 ELSE 0 END AS bit) AS [tHas_ReportAtt],
    LTRIM(RTRIM(ISNULL([tResp].[Name], N'''') + N'' '' + ISNULL([tResp].[Family], N''''))) AS [tResp_Name],
