        (N'AfterSales_ServiceRequest_Cartable', N'کارتابل مسئول منطقه', N'entities.app.sale.servicerequestdetail', N'Entities.App.Sale.ServiceRequestDetail',
         N'DECLARE @CuId BIGINT = TRY_CAST(@CurrentUserId AS BIGINT);
DECLARE @HasShowAll BIT = CASE WHEN EXISTS (
    SELECT 1
    FROM system.[User] u
    CROSS APPLY OPENJSON(ISNULL(u.RoleIds, N''[]'')) j
    INNER JOIN system.Role r ON r.Id = TRY_CAST(j.value AS bigint)
    WHERE u.Id = @CuId
      AND r.Name IN (N''Sale.ServiceRequest.ShowAll'', N''Sale.AfterSales'', N''ShowAllMenus'')
) THEN 1 ELSE 0 END;
