se,"html":"","actionScript":"function(ctx) {\n    var id = ctx && (ctx.primaryKeyValue || (ctx.primaryKeyValues && ctx.primaryKeyValues[0]) || (ctx.selectedRow && (ctx.selectedRow.t1_Id || ctx.selectedRow.id || ctx.selectedRow.Id)));\n    if (!id) { toastr.error(''لطفاً یک ردیف را انتخاب کنید''); return; }\n    var $btn = ctx.$btn ? ctx.$btn.block() : null;\n    get(''/Panel/Sale/ServiceRequestDetail/HasWorkReportAttachments?id='' + id, function (r) {\n        if ($btn) $btn.block(false);\n        if (!r || !r.isSuccess) { toastr.error((r && r.message) || ''هیچ پیوستی یافت نشد'', ''خطا''); return; }\n        var a = document.createElement(''a'');\n        a.href = ''/Panel/Sale/ServiceRequestDetail/DownloadWorkReportAttachments?id='' + id;\n        a.download = ''WorkReportAttachments_'' + id + ''.zip'';\n        document.body.appendChild(a);\n        a.click();\n        a.remove();\n    });\n}"}]'),
        (N'AfterSales_Sale_ServiceRequestPart', N'گزارش درخواست های پشتیبانی', N'entities.app.sale.servicerequest', N'Entities.App.Sale.ServiceRequest',
         N'SELECT
    [t1].[Id] AS [t1_Id],
    [tWr].[Id] AS [tWr_Id],
    CAST(CASE WHEN EXISTS (
        SELECT 1 FROM [Sale].[WorkReportAttachment] wa WHERE wa.[WorkReportId] = [tWr].[Id]
    ) THEN 1 ELSE 0 END AS bit) AS [tHas_Att],
    CASE
        WHEN CHARINDEX(N'' '', [t2].[CreatedOnShamsiDateTime]) > 0
            THEN LEFT([t2].[CreatedOnShamsiDateTime], CHARINDEX(N'' '', [t2].[CreatedOnShamsiDateTime]) - 1)
        ELSE [t2].[CreatedOnShamsiDateTime]
    END AS [tCreated_Date],
    [t2].[Id] AS [tHdr_Id],
    [t3].[Code] AS [t3_Code],
    [tOrg].[Title] AS [tOrg_Title],
    [t4].[FullName] AS [t4_FullName],
    [t5].[Title] AS [t5_Title],
    COALESCE([t4].[Phone], [t2].[CustomerPhoneFromHistory]) AS [tPhone],
    COALESCE([tAddrProv].[Name], [tCustProv].[Name]) AS [tProv_Name],
    COALESCE([tAddrZone].[Title], [tDisp].[Title]) AS [tZone_Title],
    [t2].[ExpertMission] AS [t2_ExpertMission],
    COALESCE([tOdPart].[Code], [tOth].[Code]) AS [tPart_Code],
    COALESCE([tOdPart].[Name], [tOth].[Name]) AS [tPart_Name],
    COALESCE([tSer].[Serial], [t1].[OtherPartSerial]) AS [tSerial],
    [tSer].[ProductionOrderNumber] AS [tSer_ProductionOrderNumber],
    [t1].[RequestType] AS [t1_RequestType],
    [t1].[NoticeShamsiDate] AS [t1_NoticeShamsiDate],
    [t1].[NoticeTime] AS [t1_NoticeTime],
    [tWr].[ServiceStartShamsiDate] AS [tWr_ServiceStartShamsiDate],
    [tWr].[ServiceStartTime] AS [tWr_ServiceStartTime],
    [tWr].[ServiceEndShamsiDate] AS [tWr_ServiceEndShamsiDate],
    [tWr].[ServiceEndTime] AS [tWr_ServiceEndTime],
    [t2].[Comment] AS [t2_Comment],
    (ISNULL([tM].[BreakfastFee], 0) + ISNULL([tM].[LunchFee], 0) + ISNULL([tM].[DinnerFee], 0) + ISNULL([tM].[NightRight], 0) + ISNULL([tM].[WorkOvertimeFee], 0) + ISNULL([tM].[MissionRight], 0) + ISNULL([tM].[MissionHolidayRight], 0) + ISNULL([tM].[TransportationPersonal], 0) + ISNULL([tM].[TransportationDriving], 0)) AS [tMission_Cost],
    [tM].[HokmNumber] AS [tM_HokmNumber],
    [tDur].[WaitDuration] AS [tWait_Dur],
    [tDur].[ServiceDuration] AS [tSvc_Dur],
    [tWr].[MissionResult] AS [tWr_MissionResult],
    [tHours].[SumHours] AS [tHours_Sum]
FROM [Sale].[ServiceRequestDetail] AS [t1]
INNER JOIN [Sale].[ServiceRequest] AS [t2] ON [t1].[ServiceRequestId] = [t2].[Id]
LEFT JOIN [SLS].[Customer] AS [t3] ON [t2].[CustomerId] = [t3].[Id]
LEFT JOIN [Gnr].[Party] AS [t4] ON [t3].[PartyId] = [t4].[Id]
LEFT JOIN [SLS].[CustomerAddress] AS [t5] ON [t2].[CustomerAddressId] = [t5].[Id]
LEFT JOIN [Hrm].[OrgUnit] AS [tOrg] ON [t2].[CreatedOrgUnitId] = [tOrg].[Id]
LEFT JOIN [Gnr].[Region] AS [tAddrProv] ON [t5].[ProvinceId] = [tAddrProv].[Id]
LEFT JOIN [Gnr].[Region] AS [tCustProv] ON [t3].[ProvinceId] = [tCustProv].[Id]
LEFT JOIN [Crm].[Zone] AS [tAddrZone] ON [t5].[ZoneId] = [tAddrZone].[Id]
LEFT JOIN [Crm].[Zone] AS [tDisp] ON [t2].[DispatchZoneId] = [tDisp].[Id]
LEFT JOIN [Sale].[OrderDetail] AS [tOd] ON [t1].[OrderDetailId] = [tOd].[Id]
LEFT JOIN [Inv].[Part] AS [tOdPart] ON [tOd].[PartId] = [tOdPart].[Id]
LEFT JOIN [Inv].[Part] AS [tOth] ON [t1].[OtherPartId] = [tOth].[Id]
LEFT JOIN [Sale].[OrderDetailSerial] AS [tSer] ON [t1].[OrderDetailSerialId] = [tSer].[Id]
LEFT JOIN [Sale].[WorkReport] AS [tWr] ON [tWr].[ServiceRequestDetailId] = [t1].[Id]
LEFT JOIN [Sale].[Mission] AS [tM] ON [tWr].[MissionId] = [tM].[Id]
OUTER APPLY (
    SELECT
        CASE WHEN CASE WHEN x.NoticeDt IS NULL OR x.StartDt IS NULL THEN NULL ELSE DATEDIFF(MINUTE, x.NoticeDt, x.StartDt) END IS NULL THEN NULL WHEN CASE WHEN x.NoticeDt IS NULL OR x.StartDt IS NULL THEN NULL ELSE DATEDIFF(MINUTE, x.NoticeDt, x.StartDt) END >= 60 THEN CAST(CASE WHEN x.NoticeDt IS NULL OR x.StartDt IS NULL THEN NULL ELSE DATEDIFF(MINUTE, x.NoticeDt, x.StartDt) END / 60 AS varchar(20)) + N'':'' + RIGHT(N''0'' + CAST(CASE WHEN x.NoticeDt IS NULL OR x.StartDt IS NULL THEN NULL ELSE DATEDIFF(MINUTE, x.NoticeDt, x.StartDt) END % 60 AS varchar(2)), 2) ELSE N''00:'' + CAST(CASE WHEN x.NoticeDt IS NULL OR x.StartDt IS NULL THEN NULL ELSE DATEDIFF(MINUTE, x.NoticeDt, x.StartDt) END % 60 AS varchar(20)) END AS [WaitDuration],
        CASE WHEN CASE WHEN x.StartDt IS NULL OR x.EndDt IS NULL THEN NULL ELSE DATEDIFF(MINUTE, x.StartDt, x.EndDt) END IS NULL THEN NULL WHEN CASE WHEN x.StartDt IS NULL OR x.EndDt IS NULL THEN NULL ELSE DATEDIFF(MINUTE, x.StartDt, x.EndDt) END >= 60 THEN CAST(CASE WHEN x.StartDt IS NULL OR x.EndDt IS NULL THEN NULL ELSE DATEDIFF(MINUTE, x.StartDt, x.EndDt) END / 60 AS varchar(20)) + N'':'' + RIGHT(N''0'' + CAST(CASE WHEN x.StartDt IS NULL OR x.EndDt IS NULL THEN NULL ELSE DATEDIFF(MINUTE, x.StartDt, x.EndDt) END % 60 AS varchar(2)), 2) ELSE N''00:'' + CAST(CASE WHEN x.StartDt IS NULL OR x.EndDt IS NULL THEN NULL ELSE DATEDIFF(MINUTE, x.StartDt, x.EndDt) END % 60 AS varchar(20)) END AS [ServiceDuration]
    FROM (
        SELECT
            CASE
                WHEN [t1].[NoticeShamsiDate] IS NULL OR LTRIM(RTRIM([t1].[NoticeShamsiDate])) = N'''' THEN NULL
                ELSE DATEADD(MINUTE, CASE WHEN [t1].[NoticeTime] LIKE N''[0-9][0-9]:[0-9][0-9]'' THEN TRY_CAST(LEFT([t1].[NoticeTime], 2) AS int) * 60 + TRY_CAST(RIGHT([t1].[NoticeTime], 2) AS int) ELSE 0 END, CAST(dbo.fn_ShamsiToMiladiDate([t1].[NoticeShamsiDate], N''/'') AS datetime2))
            END AS [NoticeDt],
            CASE
                WHEN [tWr].[ServiceStartMiladiDate] IS NULL THEN NULL
                ELSE DATEADD(MINUTE, CASE WHEN [tWr].[ServiceStartTime] LIKE N''[0-9][0-9]:[0-9][0-9]'' THEN TRY_CAST(LEFT([tWr].[ServiceStartTime], 2) AS int) * 60 + TRY_CAST(RIGHT([tWr].[ServiceStartTime], 2) AS int) ELSE 0 END, CAST([tWr].[ServiceStartMiladiDate] AS datetime2))
            END AS [StartDt],
            CASE
                WHEN [tWr].[ServiceEndMiladiDate] IS NULL THEN NULL
                ELSE DATEADD(MINUTE, CASE WHEN [tWr].[ServiceEndTime] LIKE N''[0-9][0-9]:[0-9][0-9]'' THEN TRY_CAST(LEFT([tWr].[ServiceEndTime], 2) AS int) * 60 + TRY_CAST(RIGHT([tWr].[ServiceEndTime], 2) AS int) ELSE 0 END, CAST([tWr].[ServiceEndMiladiDate] AS datetime2))
            END AS [EndDt]
    ) x
) AS [tDur]
OUTER APPLY (
    SELECT CASE WHEN SUM(DATEDIFF(MINUTE, y.StartDt, y.EndDt)) IS NULL THEN NULL WHEN SUM(DATEDIFF(MINUTE, y.StartDt, y.EndDt)) >= 60 THEN CAST(SUM(DATEDIFF(MINUTE, y.StartDt, y.EndDt)) / 60 AS varchar(20)) + N'':'' + RIGHT(N''0'' + CAST(SUM(DATEDIFF(MINUTE, y.StartDt, y.EndDt)) % 60 AS varchar(2)), 2) ELSE N''00:'' + CAST(SUM(DATEDIFF(MINUTE, y.StartDt, y.EndDt)) % 60 AS varchar(20)) END AS [SumHours]
    FROM [Sale].[WorkReport] wr
    CROSS APPLY (
        SELECT
            CASE
                WHEN wr.[ServiceStartMiladiDate] IS NULL THEN NULL
                ELSE DATEADD(MINUTE, CASE WHEN wr.[ServiceStartTime] LIKE N''[0-9][0-9]:[0-9][0-9]'' THEN TRY_CAST(LEFT(wr.[ServiceStartTime], 2) AS int) * 60 + TRY_CAST(RIGHT(wr.[ServiceStartTime], 2) AS int) ELSE 0 END, CAST(wr.[ServiceStartMiladiDate] AS datetime2))
            END AS [StartDt],
            CASE
                WHEN wr.[ServiceEndMiladiDate] IS NULL THEN NULL
                ELSE DATEADD(MINUTE, CASE WHEN wr.[ServiceEndTime] LIKE N''[0-9][0-9]:[0-9][0-9]'' THEN TRY_CAST(LEFT(wr.[ServiceEndTime], 2) AS int) * 60 + TRY_CAST(RIGHT(wr.[ServiceEndTime], 2) AS int) ELSE 0 END, CAST(wr.[ServiceEndMiladiDate] AS datetime2))
            END AS [EndDt]
    ) y
    WHERE wr.[ServiceRequestDetailId] = [t1].[Id]
      AND y.[StartDt] IS NOT NULL
      AND y.[EndDt] IS NOT NULL
