        (N'AfterSales_ServiceRequest_Dispatch', N'اعزام کارشناس', N'entities.app.sale.servicerequest', N'Entities.App.Sale.ServiceRequest',
         N'SELECT
    [t1].[Id] AS [t1_Id],
    [t2].[Code] AS [t2_Code],
    [t3].[FullName] AS [t3_FullName],
    CAST(CASE WHEN EXISTS (
        SELECT 1
        FROM [Sale].[ServiceRequestDetail] d
        INNER JOIN [Sale].[WorkReport] wr ON wr.[ServiceRequestDetailId] = d.[Id]
        WHERE d.[ServiceRequestId] = [t1].[Id]
    ) THEN 1 ELSE 0 END AS bit) AS [tHas_Report],
    CAST(CASE WHEN EXISTS (
        SELECT 1
        FROM [Sale].[ServiceRequestDetail] d
        INNER JOIN [Sale].[ServiceRequestPart] p ON p.[ServiceRequestDetailId] = d.[Id]
        WHERE d.[ServiceRequestId] = [t1].[Id]
    ) THEN 1 ELSE 0 END AS bit) AS [tHas_RequestPart],
    CAST(CASE WHEN EXISTS (
        SELECT 1
        FROM [Sale].[ServiceRequestDetail] d
        INNER JOIN [Sale].[WorkReport] wr ON wr.[ServiceRequestDetailId] = d.[Id]
        INNER JOIN [Sale].[WorkReportAttachment] wa ON wa.[WorkReportId] = wr.[Id]
        WHERE d.[ServiceRequestId] = [t1].[Id]
    ) THEN 1 ELSE 0 END AS bit) AS [tHas_ReportAtt],
    LTRIM(RTRIM(ISNULL([tResp].[Name], N'''') + N'' '' + ISNULL([tResp].[Family], N''''))) AS [tResp_Name],
    [t6].[Title] AS [tDisp_Title],
    [t4].[Title] AS [t4_Title],
    [t1].[ExpertMission] AS [t1_ExpertMission],
    [t1].[AllProductName] AS [t1_AllProductName],
    [t1].[CreatedByName] AS [t1_CreatedByName],
    [t1].[ContactShamsiDate] AS [t1_ContactShamsiDate],
    CASE
        WHEN CHARINDEX(N'' '', [t1].[CreatedOnShamsiDateTime]) > 0
            THEN LTRIM(RIGHT([t1].[CreatedOnShamsiDateTime], LEN([t1].[CreatedOnShamsiDateTime]) - CHARINDEX(N'' '', [t1].[CreatedOnShamsiDateTime])))
        ELSE CONVERT(nvarchar(8), [t1].[CreatedOnMiladiDateTime], 108)
    END AS [tCreated_Time],
    ISNULL([tCost].[TotalCost], CAST(0 AS bigint)) AS [tMission_Cost],
    [t1].[CustomerPhoneFromHistory] AS [t1_CustomerPhoneFromHistory],
    [t1].[CustomerAgentName] AS [t1_CustomerAgentName],
    [t1].[CustomerAgentJobPosition] AS [t1_CustomerAgentJobPosition],
    [t1].[CustomerAgentTell] AS [t1_CustomerAgentTell],
    [tRepair].[IdNumbers] AS [tRepair_Ids],
    [t1].[Comment] AS [t1_Comment]
FROM [Sale].[ServiceRequest] AS [t1]
LEFT JOIN [SLS].[Customer] AS [t2] ON [t1].[CustomerId] = [t2].[Id]
LEFT JOIN [Gnr].[Party] AS [t3] ON [t2].[PartyId] = [t3].[Id]
LEFT JOIN [SLS].[CustomerAddress] AS [t4] ON [t1].[CustomerAddressId] = [t4].[Id]
LEFT JOIN [Hcm].[Personel] AS [tResp] ON [t1].[ResponsiblePersonelId] = [tResp].[Id]
LEFT JOIN [Crm].[Zone] AS [t6] ON [t1].[DispatchZoneId] = [t6].[Id]
OUTER APPLY (
    SELECT SUM(
        ISNULL(m.[BreakfastFee], 0) + ISNULL(m.[LunchFee], 0) + ISNULL(m.[DinnerFee], 0)
        + ISNULL(m.[NightRight], 0) + ISNULL(m.[WorkOvertimeFee], 0)
        + ISNULL(m.[MissionRight], 0) + ISNULL(m.[MissionHolidayRight], 0)
        + ISNULL(m.[TransportationPersonal], 0) + ISNULL(m.[TransportationDriving], 0)
    ) AS [TotalCost]
    FROM [Sale].[Mission] m
    WHERE m.[ServiceRequestId] = [t1].[Id]
) AS [tCost]
OUTER APPLY (
    SELECT STUFF((
        SELECT N''، '' + rr.[IdNumber]
        FROM [Rpr].[RepairRequest] rr
        WHERE rr.[ServiceRequestId] = [t1].[Id]
          AND rr.[IdNumber] IS NOT NULL
          AND LTRIM(RTRIM(rr.[IdNumber])) <> N''''
        FOR XML PATH(N''''), TYPE
    ).value(N''.'', N''nvarchar(max)''), 1, 2, N'''') AS [IdNumbers]
) AS [tRepair]
