ame":""},{"TableName":"Sale.ServiceRequest","ColumnName":"t1_CustomerAgentJobPosition","DisplayName":"سمت نماینده مشتری","Alliance":"t1_CustomerAgentJobPosition","Address":"[t1].[CustomerAgentJobPosition]","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":150,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"Sale.ServiceRequest","ColumnName":"t1_CustomerAgentTell","DisplayName":"شماره همراه نماینده مشتری","Alliance":"t1_CustomerAgentTell","Address":"[t1].[CustomerAgentTell]","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":150,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"Rpr.RepairRequest","ColumnName":"tRepair_Ids","DisplayName":"شماره شناسنامه های تعمیرات","Alliance":"tRepair_Ids","Address":"[tRepair].[IdNumbers]","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":150,"Filterable":true,"Sortable":true,"ClassName":""},{"TableName":"Sale.ServiceRequest","ColumnName":"t1_Comment","DisplayName":"علت اعزام کارشناس","Alliance":"t1_Comment","Address":"[t1].[Comment]","SystemTypeName":"String","SelectIndex":0,"Visible":true,"PrimaryKey":false,"SystemType":0,"SortDirection":null,"SortOrder":null,"GroupBy":false,"Options":[],"OptionSetting":null,"Aggregate":null,"Render":null,"IsCustom":false,"CustomColType":null,"HtmlTemplate":null,"BtnConfig":null,"InputConfig":null,"Width":250,"Filterable":true,"Sortable":true,"ClassName":""}]', N'[{"dataActionName":"new","enable":true,"title":"جدید"},{"dataActionName":"edit","enable":true,"title":"ویرایش"},{"dataActionName":"delete","enable":false,"title":"حذف"},{"dataActionName":"exportExcell","enable":true,"title":"خروجی اکسل"}]', N'[{"id":"as_edit_servicerequest_dispatch","title":"ویرایش","dataActionName":"editRow","colorClass":"btn-color-primary","iconClass":"ki-pencil ki-outline","requiresSelection":true,"requiresMultiSelection":false,"useHtml":false,"html":"","actionScript":"function(ctx) {\n    var id = ctx && (ctx.primaryKeyValue || (ctx.primaryKeyValues && ctx.primaryKeyValues[0]) || (ctx.selectedRow && (ctx.selectedRow.t1_Id || ctx.selectedRow.id || ctx.selectedRow.Id)));\n    if (!id) { toastr.error(''لطفاً یک ردیف را انتخاب کنید''); return; }\n    appController.addPage(''/Panel/Sale/ServiceRequest/Edit?id='' + id, true, ''ویرایش'');\n}"}]');

    DECLARE @PName NVARCHAR(100), @PTitle NVARCHAR(200), @PEnt NVARCHAR(200), @PPascal NVARCHAR(200);
    DECLARE @PCols NVARCHAR(MAX), @PSelect NVARCHAR(MAX), @PAct NVARCHAR(MAX), @PBtn NVARCHAR(MAX);
    DECLARE @PQueryJson NVARCHAR(MAX), @PId BIGINT;

    DECLARE sr_cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT Name, Title, EntityLower, EntityPascal, ColumnsJson, CustomQuery, ActionOptions, CustomButtons FROM #SrProfiles;
    OPEN sr_cur;
    FETCH NEXT FROM sr_cur INTO @PName, @PTitle, @PEnt, @PPascal, @PCols, @PSelect, @PAct, @PBtn;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @PQueryJson = JSON_MODIFY(@QueryJsonSkeleton, '$.CustomQuery', @PSelect);

        IF EXISTS (SELECT 1 FROM system.SavedQuery WHERE Name = @PName)
        BEGIN
            UPDATE system.SavedQuery
            SET Title = @PTitle,
                QueryJson = @PQueryJson,
                ColumnsJson = @PCols,
                EntityFullName = @PEnt,
                Mode = 1,
                Type = 1,
                ActionOptions = @PAct,
                CustomActionButtonsJson = @PBtn,
                DiagramJson = N'{}',
                EventScriptsJson = N'{"onSelectedRow":"","onRowAdded":""}',
                ModifiedById = 1,
                ModifiedByName = @SeedUser,
                ModifiedDateMiladiDateTime = @Now,
                ModifiedDateShamsiDateTime = @NowShamsi,
                IsActive = 1
            WHERE Name = @PName;
            SELECT @PId = Id FROM system.SavedQuery WHERE Name = @PName;
            PRINT N'  UPDATED SavedQuery Name=' + @PName + N' Id=' + CAST(@PId AS nvarchar(20)) + N' Entity=' + @PEnt;
        END
        ELSE
        BEGIN
            INSERT INTO system.SavedQuery
                (Name, Title, QueryJson, ColumnsJson, DiagramJson, CustomActionButtonsJson, EventScriptsJson,
                 Mode, Type, EntityFullName, ActionOptions,
                 CreatedById, ModifiedById, CreatedByName, ModifiedByName,
                 CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
            VALUES
                (@PName, @PTitle, @PQueryJson, @PCols, N'{}', @PBtn, N'{"onSelectedRow":"","onRowAdded":""}',
                 1, 1, @PEnt, @PAct,
                 1, 1, @SeedUser, @SeedUser, @Now, @NowShamsi, @Now, @NowShamsi, 1);
            SET @PId = SCOPE_IDENTITY();
            PRINT N'  CREATED SavedQuery Name=' + @PName + N' Id=' + CAST(@PId AS nvarchar(20));
        END

        UPDATE #SrProfiles SET SavedQueryId = @PId WHERE Name = @PName;
        FETCH NEXT FROM sr_cur INTO @PName, @PTitle, @PEnt, @PPascal, @PCols, @PSelect, @PAct, @PBtn;
    END
    CLOSE sr_cur; DEALLOCATE sr_cur;

    PRINT N'=== Profile RoleAccess (AfterSales / ShowAllMenus + SR roles if present) ===';
    DELETE ra
    FROM system.RoleAccess ra
    INNER JOIN #SrProfiles p ON p.SavedQueryId = ra.RowId
    WHERE ra.ActionAccessType = 3;
    PRINT N'  Cleared prior profile RoleAccess: ' + CAST(@@ROWCOUNT AS nvarchar(20));

    IF OBJECT_ID('tempdb..#SrProfileRole') IS NOT NULL DROP TABLE #SrProfileRole;
    CREATE TABLE #SrProfileRole (ProfileName NVARCHAR(100) NOT NULL, RoleName NVARCHAR(200) NOT NULL);
    INSERT INTO #SrProfileRole (ProfileName, RoleName) VALUES
        (N'AfterSales_ServiceRequest_List', N'Sale.AfterSales'),
        (N'AfterSales_ServiceRequest_List', N'ShowAllMenus'),
        (N'AfterSales_ServiceRequest_List', N'Sale.ServiceRequest.Manage'),
        (N'AfterSales_ServiceRequest_List', N'Sale.ServiceRequest.View'),
        (N'AfterSales_ServiceRequest_Cartable', N'Sale.AfterSales'),
        (N'AfterSales_ServiceRequest_Cartable', N'ShowAllMenus'),
        (N'AfterSales_ServiceRequest_Cartable', N'Sale.ServiceRequest.Manage'),
        (N'AfterSales_ServiceRequest_Cartable', N'Sale.ServiceRequest.View'),
        (N'AfterSales_ServiceRequest_Cartable', N'Sale.ServiceRequest.ShowAll'),
        (N'AfterSales_Sale_ServiceRequestPart', N'Sale.AfterSales'),
        (N'AfterSales_Sale_ServiceRequestPart', N'ShowAllMenus'),
        (N'AfterSales_Sale_ServiceRequestPart', N'Sale.ServiceRequest.Manage'),
        (N'AfterSales_Sale_ServiceRequestPart', N'Sale.ServiceRequest.View'),
        (N'AfterSales_ServiceRequest_Dispatch', N'Sale.AfterSales'),
        (N'AfterSales_ServiceRequest_Dispatch', N'ShowAllMenus'),
        (N'AfterSales_ServiceRequest_Dispatch', N'Sale.ServiceRequest.Manage'),
        (N'AfterSales_ServiceRequest_Dispatch', N'Sale.ServiceRequest.View'),
        (N'AfterSales_WorkReport_List', N'Sale.AfterSales'),
        (N'AfterSales_WorkReport_List', N'ShowAllMenus'),
        (N'AfterSales_WorkReport_List', N'Sale.ServiceRequest.Manage'),
        (N'AfterSales_WorkReport_List', N'Sale.ServiceRequest.View'),
        (N'AfterSales_WorkReport_List', N'Sale.ServiceRequest.ShowAll'),
        (N'AfterSales_ServiceRequestPart_List', N'Sale.AfterSales'),
        (N'AfterSales_ServiceRequestPart_List', N'ShowAllMenus'),
        (N'AfterSales_ServiceRequestPart_List', N'Sale.ServiceRequest.Manage'),
        (N'AfterSales_ServiceRequestPart_List', N'Sale.ServiceRequest.View'),
        (N'AfterSales_ServiceRequestPart_List', N'Sale.ServiceRequest.ShowAll');

    INSERT INTO system.RoleAccess
        (Path, ActionAccessType, ActionAccessItemType, EntityName, DisplayName, EntityId, RowId, RoleId,
         CreatedById, ModifiedById, CreatedByName, ModifiedByName,
         CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
    SELECT DISTINCT
        N'dataProfile_' + CAST(p.SavedQueryId AS nvarchar(20)),
        3, 7, p.EntityPascal, p.Title, NULL, p.SavedQueryId, r.Id,
        1, 1, @SeedUser, @SeedUser, @Now, @NowShamsi, @Now, @NowShamsi, 1
    FROM #SrProfileRole map
    INNER JOIN #SrProfiles p ON p.Name = map.ProfileName
    INNER JOIN system.Role r ON r.Name = map.RoleName
    WHERE p.SavedQueryId IS NOT NULL;
    PRINT N'  Inserted DataProfile RoleAccess: ' + CAST(@@ROWCOUNT AS nvarchar(20));

    INSERT INTO system.RoleAccess
        (Path, ActionAccessType, ActionAccessItemType, EntityName, DisplayName, EntityId, RowId, RoleId,
         CreatedById, ModifiedById, CreatedByName, ModifiedByName,
         CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
    SELECT DISTINCT
        N'dataProfile_' + CAST(q.Id AS nvarchar(20)),
        3, 7, q.EntityFullName, q.Title, NULL, q.Id, r.Id,
        1, 1, @SeedUser, @SeedUser, @Now, @NowShamsi, @Now, @NowShamsi, 1
    FROM #SrProfileRole map
    INNER JOIN system.SavedQuery q ON q.Name = map.ProfileName
    INNER JOIN system.Role r ON r.Name = map.RoleName
    WHERE NOT EXISTS (
        SELECT 1 FROM #SrProfiles p WHERE p.Name = map.ProfileName
    )
      AND NOT EXISTS (
        SELECT 1 FROM system.RoleAccess x
        WHERE x.ActionAccessType = 3 AND x.RowId = q.Id AND x.RoleId = r.Id
    );
    PRINT N'  Inserted catalog profile RoleAccess: ' + CAST(@@ROWCOUNT AS nvarchar(20));

    COMMIT TRANSACTION;
    PRINT N'=== DONE Seed_SaleServiceRequest_DataProfiles ===';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    DECLARE @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE();
    DECLARE @ErrSeverity INT = ERROR_SEVERITY();
    DECLARE @ErrState INT = ERROR_STATE();
    PRINT N'=== ERROR rolled back ===';
    RAISERROR(@ErrMsg, @ErrSeverity, @ErrState);
END CATCH;

PRINT N'--- verify profiles ---';
SELECT Id, Name, Title, EntityFullName, Mode, Type
FROM system.SavedQuery
WHERE Name IN (N'AfterSales_ServiceRequest_List', N'AfterSales_ServiceRequest_Cartable', N'AfterSales_Sale_ServiceRequestPart', N'AfterSales_ServiceRequest_Dispatch')
ORDER BY Name;

PRINT N'--- verify column Alliance order ---';
SELECT q.Name, TRY_CAST(j.[key] AS int) AS ColIndex,
       JSON_VALUE(j.value, '$.Alliance') AS Alliance,
       JSON_VALUE(j.value, '$.ColumnName') AS ColumnName,
       JSON_VALUE(j.value, '$.DisplayName') AS DisplayName,
       JSON_VALUE(j.value, '$.Visible') AS Visible,
       JSON_VALUE(j.value, '$.PrimaryKey') AS PrimaryKey
FROM system.SavedQuery q
CROSS APPLY OPENJSON(q.ColumnsJson) j
WHERE q.Name IN (N'AfterSales_ServiceRequest_List', N'AfterSales_ServiceRequest_Cartable', N'AfterSales_Sale_ServiceRequestPart', N'AfterSales_ServiceRequest_Dispatch')
ORDER BY q.Name, TRY_CAST(j.[key] AS int);

SELECT CASE WHEN JSON_VALUE(j.value, '$.Alliance') = JSON_VALUE(j.value, '$.ColumnName') THEN 1 ELSE 0 END AS AllianceEqualsColumnName,
       COUNT(*) AS Cnt
FROM system.SavedQuery q
CROSS APPLY OPENJSON(q.ColumnsJson) j
WHERE q.Name IN (N'AfterSales_ServiceRequest_List', N'AfterSales_ServiceRequest_Cartable', N'AfterSales_Sale_ServiceRequestPart', N'AfterSales_ServiceRequest_Dispatch')
GROUP BY CASE WHEN JSON_VALUE(j.value, '$.Alliance') = JSON_VALUE(j.value, '$.ColumnName') THEN 1 ELSE 0 END;
